package com.sliverzfx.gothicquest

/** Independently written reference notes; see docs/sources/remaining-game-tools-sources.md. */
internal object NewBalanceToolsData {
    const val sourceNote = "New Balance • PC Marvin / community code snapshot November 2025"
    val codes = listOf(
        ToolReferenceEntry("nb_setup", "SETUP", "New Balance Marvin mode", "New Balance builds can change or restrict debug mode. On builds supporting the Pause/Break method, pause, type marvin, then press Esc to return; F2 opens the console once debug mode is active. This sequence is community-reported, not guaranteed for every release. Save separately before experimenting. Do not use resurrection to recover a progression-critical death.", command = null, source = "https://www.reddit.com/r/worldofgothic/comments/1362wya", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("nb_version", "SETUP", "Match your New Balance version", "These are New Balance references, not vanilla Night of the Raven statistics. The community code table notes a November 2025 translation snapshot; later builds and optional systems can change availability and bonuses. Use your in-game item description as the final check.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/kody-a-marvin", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("nb_spawn_help", "CONSOLE", "How item and NPC insertion works", "With a compatible Marvin mode active, open F2 and enter insert followed by the exact instance ID. The reference commands create a new instance; they do not move the existing story NPC or complete the original quest. Keep a separate save before spawning anything tied to a quest.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/kody-a-marvin", codeCategory = CodeCategory.GENERAL),
        ToolReferenceEntry("nb_console", "SHORTCUTS", "Open the debug console", "Press F2 after enabling the debug mode supported by your installed New Balance build. Activation and allowed shortcuts can differ between releases.", command = "F2", source = "https://www.reddit.com/r/worldofgothic/comments/1362wya", codeCategory = CodeCategory.GENERAL)
    ) + NewBalanceInstanceData.entries + NewBalanceEquipmentData.entries
    val items = emptyList<ToolReferenceEntry>()
    val tips = listOf(
        ToolReferenceEntry("nb_tip_bosper", "GAMEPLAY", "Bosper’s apprentice benefits", "Bosper’s apprenticeship can provide free fang extraction and discounted claw extraction. Ask about these benefits before spending learning points elsewhere. Check the offers in your build before committing.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_harad", "GAMEPLAY", "Harad and smithing", "Harad’s apprentices can learn basic smithing without spending learning points. Pick an apprenticeship that supports your intended income and crafting route.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_constantino", "GAMEPLAY", "Constantino’s first recipe", "Constantino’s apprenticeship offers a choice of an introductory health, mana or stamina potion recipe. Compare your build’s immediate needs before selecting one.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_mushrooms", "GAMEPLAY", "Ask about the mushrooms", "As Constantino’s apprentice, handing over two dozen mushrooms and asking why they matter can grant an extra learning point. Read the dialogue before selling your mushroom stock.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_dragomir", "GAMEPLAY", "A hunting lesson from a book", "Returning Dragomir’s crossbow can provide the Hornets book. Read it for bloodfly stinger extraction before paying for the same skill.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_smelting", "GAMEPLAY", "Look for the gold-smelting book", "A book in the gold mine above the passage toward Khorinis can teach gold smelting. Check the table at the end of the mine before paying a teacher.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_orc_language", "GAMEPLAY", "An orc-language textbook", "The locked chest in the old Xardas tower contains an orc-language textbook. Prepare for a ghost encounter when opening it, and keep a manual save before entering.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_orc_fangs", "GAMEPLAY", "Ur-Karras can teach fangs", "If fang extraction is still unlearned, the rescued Ur-Karras can teach it during Hunt for Muritan. Check this route before buying the skill.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_ore", "GAMEPLAY", "Clovis and ore mining", "In the Orc Mine, Clovis can teach ore mining after you bring the daily quota. Speak to him before spending learning points on duplicate training.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_necromancer", "GAMEPLAY", "Necromancer mana regeneration", "For a Necromancer, check Xardas and Kreol for mana-regeneration training. Their class-specific route differs from the general training offered to other characters.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_resistance", "GAMEPLAY", "Choose the resistance potion route", "Zuris’s dialogue concerning Eligor’s Flame affects access to Nefarius’s Icy Shroud route. Save before choosing, and follow the relevant quest notes if you want cold resistance.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/levne-dovednosti", codeCategory = null),
        ToolReferenceEntry("nb_tip_build", "GAMEPLAY", "Plan one build before spending", "New Balance adds specialist paths and different combat calculations. Decide which weapon or magic path you want before spreading learning points across unrelated systems. Check the requirements on your next actual upgrade.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/plan-buildu", codeCategory = null),
        ToolReferenceEntry("nb_tip_bonuses", "GAMEPLAY", "Track permanent bonuses", "Recipes, food, divine gifts and permanent potions are separate bonus sources. Keep a record of what your character has already consumed; totals in a planning guide are not a guarantee for every difficulty or optional mode.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/plan-buildu", codeCategory = null),
        ToolReferenceEntry("nb_tip_asnc", "GAMEPLAY", "Check whether ASnC is enabled", "ASnC has its own progression and bonus rules. Confirm your chosen mode before applying a standard build plan or comparing boss-extract rewards.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/asnc-rozdeleni-statu", codeCategory = null),
        ToolReferenceEntry("nb_tip_wisp", "GAMEPLAY", "Invest in the collecting wisp", "New Balance includes a trainable wisp that can collect items. Check its available upgrades as part of your exploration routine.", command = null, source = "https://www.myrtana.net/en/new-balance/wiki/dovednosti-prehled", codeCategory = null)
    )
    fun entries(section: ToolSection): List<ToolReferenceEntry> = when (section) {
        ToolSection.MARVIN_CODES -> codes
        ToolSection.ITEMS -> items
        ToolSection.USEFUL_TIPS -> tips
    }
}
